def countFallingPaths(grid):
    MOD = 10 ** 9 + 7
    n = len(grid[0])
    cur = [1 - v for v in grid[0]]
    for row in grid[1:]:
        nxt = [0] * n
        for c in range(n):
            if row[c] == 0:
                s = cur[c]
                if c > 0:
                    s += cur[c - 1]
                if c < n - 1:
                    s += cur[c + 1]
                nxt[c] = s % MOD
        cur = nxt
    return sum(cur) % MOD
